### Describe the bug

when using raw html inside a `<template>` tag, the rendered template element is empty.

```html
[<template>{@html '<b>hello</b>'}</template>]
```

![image](https://user-images.githubusercontent.com/8693091/155658428-cf602591-8796-4c90-9e3e-3098fc11ce19.png)


compiled (repl version=3.46.4)
```js
function create_fragment(ctx) {
	let template;
	let raw_value = 'hello' + "";

	return {
		c() {
			template = element("template");
		},
		m(target, anchor) {
			insert(target, template, anchor);
			template.content.innerHTML = raw_value;   // <----------------- should be template.innerHTML
		},
		p: noop,
		i: noop,
		o: noop,
		d(detaching) {
			if (detaching) detach(template);
		}
	};
}
```

### Reproduction
```html
[<template>{@html 'hello' }</template>]
```

